SourceCode.Declaration:
/// <summary>
/// Chain of Command extension on <c>DirPerson</c> to detect person name, alias, or gender updates
/// and resolve the linked <c>CustTable</c> record in company 'utc' for Salesforce synchronization.
/// </summary>
[ExtensionOf(tableStr(DirPerson))]
public final class UTCSFDirPerson_Extension
{
}

Method.Source:
public void update()
{
    DirPerson origPerson    = this.orig();
    boolean   hasNameChange = (this.Name      != origPerson.Name
                            || this.NameAlias != origPerson.NameAlias
                            || this.Gender    != origPerson.Gender);

    next update();

    if (hasNameChange)
    {
        UTCSFCustomerChangeHandler::tryEnqueueByPartyRecId(this.RecId);
    }
}
